at::Tensor matmul_with_small_k_dimension_custom_impl_npu(const at::Tensor& A, const at::Tensor& B) {
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, \"Inputs must be 2-D tensors\");
    TORCH_CHECK(A.size(1) == B.size(0), \"Incompatible shapes for matmul\");
    at::Tensor C = at::empty({A.size(0), B.size(1)}, A.options());
    EXEC_NPU_CMD(aclnnMatmulWithSmallKDimensionCustom, A, B, C);
    return C;
